CREATE TABLE profiles (
  id         TEXT PRIMARY KEY,
  email      TEXT NOT NULL,
  full_name  TEXT,
  is_demo    INTEGER NOT NULL DEFAULT 0 CHECK (is_demo IN (0, 1)),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
INSERT INTO "profiles" ("id","email","full_name","is_demo","created_at","updated_at") VALUES('ccc2a329-a7a0-4147-ba6d-827934124a5b','designwithnihar@gmail.com',NULL,0,'2026-10-15 16:56:24','2026-10-15 16:56:24');
CREATE TABLE campaigns (
  id                           TEXT PRIMARY KEY,
  owner_id                     TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  name                         TEXT NOT NULL,
  status                       TEXT NOT NULL DEFAULT 'draft'
                                 CHECK (status IN ('draft','active','paused','completed')),
  niche                        TEXT NOT NULL,
  geography                    TEXT,
  ideal_customer_description   TEXT NOT NULL DEFAULT '',
  offer                        TEXT NOT NULL DEFAULT '',
  value_proposition            TEXT NOT NULL DEFAULT '',
  case_study_url               TEXT,
  minimum_score                INTEGER NOT NULL DEFAULT 60,
  notes                        TEXT,
  created_at                   TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at                   TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
INSERT INTO "campaigns" ("id","owner_id","name","status","niche","geography","ideal_customer_description","offer","value_proposition","case_study_url","minimum_score","notes","created_at","updated_at") VALUES('cmp_mumbai_jewellery_q4','ccc2a329-a7a0-4147-ba6d-827934124a5b','Mumbai Jewellery Studios — Q4','active','Jewellery & luxury','{"city":"Mumbai","region":"Maharashtra","country":"India"}','Independent fine-jewellery studios with physical presence in South and Central Mumbai whose website doesn''t match the quality of their work.','Website redesign with product storytelling and enquiry capture','A storefront that treats jewellery like editorial — high-fidelity imagery, clean typography, and a direct line to the studio.','https://dwn-site.pages.dev/case-studies/jewellery-studio',60,'Follow-up window: 10 working days. Focus on Fort / Lower Parel first.','2026-09-16T09:00:00.000Z','2026-10-12T09:00:00.000Z');
INSERT INTO "campaigns" ("id","owner_id","name","status","niche","geography","ideal_customer_description","offer","value_proposition","case_study_url","minimum_score","notes","created_at","updated_at") VALUES('cmp_d2c_audits','ccc2a329-a7a0-4147-ba6d-827934124a5b','D2C Brand Audits','active','D2C consumer brands','{"city":"Mumbai","region":"Maharashtra","country":"India"}','Direct-to-consumer brands in skincare, food, wellness, and apparel with a working storefront but visible conversion gaps.','Conversion audit + landing-page redesign','An honest look at what''s leaking traffic, with a focused rebuild of the one page that matters most.',NULL,55,'Avoid brands that already have an in-house design team.','2026-09-02T09:00:00.000Z','2026-10-09T09:00:00.000Z');
INSERT INTO "campaigns" ("id","owner_id","name","status","niche","geography","ideal_customer_description","offer","value_proposition","case_study_url","minimum_score","notes","created_at","updated_at") VALUES('cmp_restaurant_mobile','ccc2a329-a7a0-4147-ba6d-827934124a5b','Restaurant Mobile-First','active','Restaurants & hospitality','{"city":"Mumbai","region":"Maharashtra","country":"India"}','Restaurants and cafés whose website renders poorly on mobile or hides the menu behind a PDF.','Mobile-first website rebuild with online menu and reservations','A site that opens cleanly on a phone, shows the menu first, and lets guests book without calling.',NULL,60,NULL,'2026-09-23T09:00:00.000Z','2026-10-13T09:00:00.000Z');
INSERT INTO "campaigns" ("id","owner_id","name","status","niche","geography","ideal_customer_description","offer","value_proposition","case_study_url","minimum_score","notes","created_at","updated_at") VALUES('cmp_clinic_websites','ccc2a329-a7a0-4147-ba6d-827934124a5b','Clinic Websites','paused','Clinics & local services','{"city":"Mumbai","region":"Maharashtra","country":"India"}','Independent clinics (dental, dermatology, ayurveda) with no website or outdated info and broken contact paths.','Clinic website with appointment enquiry flow','A trustworthy clinic site that lets patients find hours, services, and a way to book without picking up the phone.',NULL,60,'Paused while we revalidate medical-council disclosure requirements.','2026-08-15T09:00:00.000Z','2026-09-30T09:00:00.000Z');
INSERT INTO "campaigns" ("id","owner_id","name","status","niche","geography","ideal_customer_description","offer","value_proposition","case_study_url","minimum_score","notes","created_at","updated_at") VALUES('cmp_smb_automation','ccc2a329-a7a0-4147-ba6d-827934124a5b','Automation for SMBs','draft','SMB operations','{"city":"Mumbai","region":"Maharashtra","country":"India"}','Small and mid-sized businesses whose operations run through spreadsheets, email threads, and manual data entry.','Scoped automation sprint — one workflow replaced per engagement','The one repetitive workflow that eats a day a week, replaced with software that just works.',NULL,55,'Draft — still shaping the pitch.','2026-10-07T09:00:00.000Z','2026-10-07T09:00:00.000Z');
CREATE TABLE leads (
  id                      TEXT PRIMARY KEY,
  owner_id                TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  business_name           TEXT NOT NULL,
  normalized_name         TEXT NOT NULL,
  category                TEXT NOT NULL DEFAULT '',
  niche                   TEXT NOT NULL,
  website_url             TEXT,
  normalized_domain       TEXT,
  public_email            TEXT,
  public_phone            TEXT,
  address                 TEXT,
  city                    TEXT NOT NULL DEFAULT '',
  region                  TEXT,
  country                 TEXT NOT NULL DEFAULT 'India',
  source_name             TEXT NOT NULL DEFAULT 'manual',
  source_url              TEXT,
  source_external_id      TEXT,
  source_last_checked_at  TEXT,
  website_condition       TEXT NOT NULL DEFAULT 'unknown'
                            CHECK (website_condition IN
                              ('no_website','inaccessible','outdated','weak','acceptable','strong','unknown')),
  fit_score               INTEGER,
  evidence_confidence     TEXT NOT NULL DEFAULT 'insufficient'
                            CHECK (evidence_confidence IN ('low','medium','high','insufficient')),
  score_band              TEXT
                            CHECK (score_band IS NULL OR score_band IN
                              ('priority_review','strong_candidate','needs_manual_review','low_priority','insufficient_evidence')),
  score_breakdown         TEXT,
  score_version           TEXT,
  scored_at               TEXT,
  pipeline_stage          TEXT NOT NULL DEFAULT 'new'
                            CHECK (pipeline_stage IN
                              ('new','reviewing','qualified','contacted','replied',
                               'meeting_booked','proposal_sent','won','lost','not_a_fit')),
  estimated_deal_value    INTEGER,
  currency                TEXT NOT NULL DEFAULT 'INR',
  loss_reason             TEXT,
  last_contacted_at       TEXT,
  next_action_at          TEXT,
  tags                    TEXT NOT NULL DEFAULT '[]',
  do_not_contact          INTEGER NOT NULL DEFAULT 0 CHECK (do_not_contact IN (0, 1)),
  do_not_contact_reason   TEXT,
  do_not_contact_at       TEXT,
  created_at              TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at              TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  archived_at             TEXT,
  CHECK (fit_score IS NULL OR (fit_score >= 0 AND fit_score <= 100))
);
