CREATE TABLE discovery_jobs (
  id                TEXT PRIMARY KEY,
  owner_id          TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  campaign_id       TEXT REFERENCES campaigns(id) ON DELETE SET NULL,
  source_name       TEXT NOT NULL,
