CREATE TABLE lead_sources (
  id                         TEXT PRIMARY KEY,
  lead_id                    TEXT NOT NULL REFERENCES leads(id) ON DELETE CASCADE,
  source_name                TEXT NOT NULL,
  source_url                 TEXT,
  external_id                TEXT,
  observed_at                TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  permitted_storage_policy   TEXT,
  evidence                   TEXT
);
CREATE TABLE website_audits (
  id             TEXT PRIMARY KEY,
  lead_id        TEXT NOT NULL REFERENCES leads(id) ON DELETE CASCADE,
  requested_url  TEXT NOT NULL,
  final_url      TEXT,
  status         TEXT NOT NULL
                   CHECK (status IN ('success','partial','blocked','unavailable','failed')),
  http_status    INTEGER,
  audit_version  TEXT NOT NULL,
  findings       TEXT NOT NULL DEFAULT '[]',
  metrics        TEXT,
  error_category TEXT,
  started_at     TEXT NOT NULL,
  completed_at   TEXT
);
INSERT INTO "website_audits" ("id","lead_id","requested_url","final_url","status","http_status","audit_version","findings","metrics","error_category","started_at","completed_at") VALUES('aud_rani_01','lead_rani_heritage','https://rani-heritage.example','https://rani-heritage.example/','success',200,'audit/v0.1','[{"code":"missing_viewport","title":"Missing viewport meta tag","severity":"medium","description":"The homepage HTML does not declare a viewport, which causes mobile browsers to render a scaled desktop layout.","evidence":"No <meta name=\"viewport\"> tag in <head>","evidenceUrl":"https://rani-heritage.example","confidence":"high","recommendation":"Add <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"> and verify responsive breakpoints."},{"code":"stale_blog","title":"Blog content hasn''t been updated since 2019","severity":"low","description":"Latest blog post dated 11 July 2019. Stale content signals a dormant site to visitors.","evidence":"Blog archive page lists 2019 as most recent year","evidenceUrl":"https://rani-heritage.example/blog","confidence":"high","recommendation":"Either hide the blog section or publish 2–3 updated posts tied to collection launches."},{"code":"weak_contact_path","title":"No visible business email on contact page","severity":"medium","description":"Enquiry form present, but the contact page lists no email address and no WhatsApp link.","evidence":"Contact page analysed; only a form exists","evidenceUrl":"https://rani-heritage.example/contact","confidence":"high","recommendation":"Publish a dedicated business email and a WhatsApp link; forms are a known friction point for jewellery buyers."}]','{"source":"server-fetch","pageWeightBytes":2840000,"loadMs":4100,"note":"Server-observed timing on a bounded fetch. Not a real-user measurement."}',NULL,'2026-10-12T09:00:00.000Z','2026-10-12T09:00:00.000Z');
INSERT INTO "website_audits" ("id","lead_id","requested_url","final_url","status","http_status","audit_version","findings","metrics","error_category","started_at","completed_at") VALUES('aud_lotus_01','lead_lotus_skincare','https://lotus-skincare.example','https://lotus-skincare.example/','success',200,'audit/v0.1','[{"code":"cta_hierarchy","title":"Three competing CTAs above the fold","severity":"medium","description":"The hero shows a Shop CTA, a Quiz CTA, and a Newsletter CTA at similar visual weight.","evidence":"Three primary buttons within hero section","evidenceUrl":"https://lotus-skincare.example","confidence":"medium","recommendation":"Pick one primary action per landing. The Quiz tested well on paid traffic — consider leading with that."},{"code":"no_viewport","title":"Viewport meta tag missing","severity":"medium","description":"Mobile viewport is scaled desktop. The quiz is unusable on narrow screens.","evidence":"Audit HTML scan — no viewport declaration","confidence":"high","recommendation":"Add the standard responsive viewport declaration."},{"code":"slow_hero_image","title":"Hero image is 1.4 MB","severity":"medium","description":"Hero asset is a 2600×1400 JPEG at ~1.4 MB. First paint delayed noticeably on mid-range phones.","evidence":"Measured during server fetch","confidence":"medium","recommendation":"Export a 1600w variant with AVIF/WebP and lazy-load secondary images."}]','{"source":"server-fetch","pageWeightBytes":1820000,"loadMs":2600,"note":"Static HTML timing only — this is not a Core Web Vitals measurement."}',NULL,'2026-10-11T09:00:00.000Z','2026-10-11T09:00:00.000Z');
INSERT INTO "website_audits" ("id","lead_id","requested_url","final_url","status","http_status","audit_version","findings","metrics","error_category","started_at","completed_at") VALUES('aud_marine_01','lead_marine_drive','https://marinedrive-bistro.example',NULL,'unavailable',522,'audit/v0.1','[{"code":"site_unavailable","title":"Website returned HTTP 522 on three consecutive attempts","severity":"high","description":"The server at marinedrive-bistro.example timed out on each audit attempt in a 48h window. This may be a hosting issue, a DNS misconfiguration, or an abandoned domain.","evidence":"3 attempts, all 522 (upstream connection timed out)","confidence":"high","recommendation":"Flag this as a credible first conversation starter — their site is effectively offline. Confirm by hand once before outreach."}]',NULL,'upstream_timeout','2026-10-12T09:00:00.000Z','2026-10-12T09:00:00.000Z');
INSERT INTO "website_audits" ("id","lead_id","requested_url","final_url","status","http_status","audit_version","findings","metrics","error_category","started_at","completed_at") VALUES('aud_ksh_01','lead_koramangala_social','https://ksh.example','https://ksh.example/','success',200,'audit/v0.1','[{"code":"mobile_broken","title":"Mobile layout triggers horizontal scroll","severity":"high","description":"At 375w viewport the menu grid overflows the viewport by ~80px.","evidence":"Audit DOM measurement","confidence":"medium","recommendation":"Rebuild the menu as a mobile-first stack."},{"code":"pdf_menu","title":"Menu is a PDF download, not web content","severity":"medium","description":"The /menu route serves a 1.2 MB PDF rather than HTML. Guests on mobile data abandon the site.","evidence":"GET /menu returned Content-Type: application/pdf","confidence":"high","recommendation":"Publish the menu as structured HTML with filterable sections."}]','{"source":"server-fetch","pageWeightBytes":3200000,"loadMs":5800}',NULL,'2026-10-12T09:00:00.000Z','2026-10-12T09:00:00.000Z');
INSERT INTO "website_audits" ("id","lead_id","requested_url","final_url","status","http_status","audit_version","findings","metrics","error_category","started_at","completed_at") VALUES('aud_ayur_01','lead_ayur_bandra','https://ayurclinic-bandra.example','http://ayurclinic-bandra.example/','partial',200,'audit/v0.1','[{"code":"no_https","title":"Site served over HTTP, not HTTPS","severity":"high","description":"Browser will show a ''Not Secure'' warning on every page.","evidence":"Request redirected HTTPS→HTTP","confidence":"high","recommendation":"Install a free TLS certificate (Let''s Encrypt). This is table stakes for a clinic site."},{"code":"broken_form","title":"Contact form submit returns 500","severity":"high","description":"POST to the contact form endpoint returns 500 Internal Server Error. Patients cannot enquire via web.","evidence":"Test submission failed on audit","evidenceUrl":"https://ayurclinic-bandra.example/contact","confidence":"medium","recommendation":"Replace the broken form handler. In the interim, a WhatsApp Business link would be a 10-minute fix."}]','{"source":"server-fetch","pageWeightBytes":980000,"loadMs":3100}',NULL,'2026-10-12T09:00:00.000Z','2026-10-12T09:00:00.000Z');
INSERT INTO "website_audits" ("id","lead_id","requested_url","final_url","status","http_status","audit_version","findings","metrics","error_category","started_at","completed_at") VALUES('aud_soma_01','lead_soma_wellness','https://soma-teas.example','http://soma-teas.example/','partial',200,'audit/v0.1','[{"code":"no_https","title":"Site served over HTTP only","severity":"high","description":"Checkout page is not served over HTTPS. This is a trust and compliance issue for anything collecting payment data.","evidence":"Checkout URL served http://","confidence":"high","recommendation":"Enforce HTTPS site-wide before any new campaigns run."},{"code":"old_theme","title":"Shopify theme is 5+ years old","severity":"medium","description":"Visible markers in the DOM (old liquid tags, deprecated snippets) suggest a 2019-era theme.","evidence":"DOM scan + theme marker in <head>","confidence":"medium","recommendation":"Consider a focused Shopify redesign — the brand photography deserves a better frame."}]','{"source":"server-fetch","pageWeightBytes":2100000,"loadMs":3800}',NULL,'2026-10-09T09:00:00.000Z','2026-10-09T09:00:00.000Z');
INSERT INTO "website_audits" ("id","lead_id","requested_url","final_url","status","http_status","audit_version","findings","metrics","error_category","started_at","completed_at") VALUES('aud_papertrail_01','lead_papertrail_logistics','https://papertrail-logistics.example','https://papertrail-logistics.example/','success',200,'audit/v0.1','[{"code":"site_ok","title":"Website passes baseline checks","severity":"info","description":"The marketing site is in good shape. The opportunity here is the operational workflow behind the business, not the public site.","evidence":"Audit baseline clean","confidence":"high","recommendation":"Skip website pitch. Lead with an automation scoping conversation."}]','{"source":"server-fetch","pageWeightBytes":1240000,"loadMs":1900}',NULL,'2026-10-08T09:00:00.000Z','2026-10-08T09:00:00.000Z');
