INSERT INTO "website_audits" ("id","lead_id","requested_url","final_url","status","http_status","audit_version","findings","metrics","error_category","started_at","completed_at") VALUES('af85de81-3941-4007-a519-d47af401d17c','d1f284f6-d93b-4a3c-b9f7-f740823dafcd','https://mangalroyaljewelspvtltd.com','https://mangalroyaljewelspvtltd.com/','unavailable',530,'audit/v0.1','[{"code":"fetch_http_error","title":"Server returned an error status","severity":"high","description":"Server returned HTTP 530.","evidence":"Requested: https://mangalroyaljewelspvtltd.com · HTTP 530","evidenceUrl":"https://mangalroyaljewelspvtltd.com/","confidence":"high","recommendation":"The server returned a non-success status. If it''s a 404 the content moved; if it''s a 5xx the host is unstable."}]',NULL,'http_error','2026-10-15T18:06:47.010Z','2026-10-15T18:06:47.069Z');
