CREATE TABLE opportunity_briefs (
  id                     TEXT PRIMARY KEY,
  lead_id                TEXT NOT NULL REFERENCES leads(id) ON DELETE CASCADE,
  campaign_id            TEXT REFERENCES campaigns(id) ON DELETE SET NULL,
  summary                TEXT NOT NULL,
  observations           TEXT NOT NULL DEFAULT '[]',
  possible_opportunity   TEXT NOT NULL DEFAULT '',
  recommended_service    TEXT NOT NULL DEFAULT '',
  suggested_deliverable  TEXT NOT NULL DEFAULT '',
  confidence             TEXT NOT NULL DEFAULT 'medium'
                           CHECK (confidence IN ('low','medium','high')),
  unknowns               TEXT NOT NULL DEFAULT '[]',
  source                 TEXT NOT NULL DEFAULT 'template'
                           CHECK (source IN ('template','ai')),
  model_metadata         TEXT,
  created_at             TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
INSERT INTO "opportunity_briefs" ("id","lead_id","campaign_id","summary","observations","possible_opportunity","recommended_service","suggested_deliverable","confidence","unknowns","source","model_metadata","created_at") VALUES('brief_haveli','lead_haveli','cmp_mumbai_jewellery_q4','A heritage jewellery studio operating entirely off WhatsApp and Instagram. There''s no website today, which caps how far their reputation can travel beyond the regulars.','[{"observation":"No website is reachable at any variant of their business name.","evidence":"Manual search + domain check"},{"observation":"Instagram presence is active with multiple posts within the past two weeks.","evidence":"Instagram feed check"}]','A focused brand site that treats their inventory like editorial — stories per collection, direct WhatsApp enquiry on every piece. No e-commerce until that proves itself.','Website design & build','A 6–8 page brand site with a WhatsApp-first enquiry flow.','medium','["Who is the decision-maker for digital presence?","Do they have usable product photography, or does photography need to be in scope?"]','template',NULL,'2026-10-13T09:00:00.000Z');
INSERT INTO "opportunity_briefs" ("id","lead_id","campaign_id","summary","observations","possible_opportunity","recommended_service","suggested_deliverable","confidence","unknowns","source","model_metadata","created_at") VALUES('brief_marine','lead_marine_drive','cmp_restaurant_mobile','A Marine Drive restaurant whose website has been unreachable for at least 48 hours. Google reviews within the last week confirm the restaurant itself is operating.','[{"observation":"Website returned HTTP 522 on three consecutive audit attempts over 48h.","evidence":"aud_marine_01"},{"observation":"Google Business listing shows reviews within the last 5 days.","evidence":"Public Google Business profile"}]','A new mobile-first site with a working menu and reservations. The current pitch opens itself — their site is effectively offline.','Website design & build','A one-page site with menu, reservation form, and a tap-to-call CTA.','high','["Is the current hosting a lapsed renewal or an active decision to let it expire?"]','template',NULL,'2026-10-12T09:00:00.000Z');
INSERT INTO "opportunity_briefs" ("id","lead_id","campaign_id","summary","observations","possible_opportunity","recommended_service","suggested_deliverable","confidence","unknowns","source","model_metadata","created_at") VALUES('brief_papertrail','lead_papertrail_logistics','cmp_smb_automation','A mid-market logistics firm hiring ops interns ''to help manage spreadsheets''. Their public website is fine; the operational workflow isn''t.','[{"observation":"LinkedIn job listings mention manual spreadsheet management as a daily task.","evidence":"Public LinkedIn jobs page","evidenceUrl":"https://linkedin.example/papertrail-logistics/jobs"},{"observation":"The company has posted about process improvement on LinkedIn within the last 10 days.","evidence":"Company LinkedIn feed"}]','An automation sprint focused on the single workflow eating the most hours — likely an inbound order triage or carrier dispatch handoff.','AI workflow automation','A 4-week scoped sprint with one workflow replaced end-to-end.','high','["Which specific workflow is the biggest time sink?","What tools are they already using (airtable? Zoho? internal Excel?)"]','template',NULL,'2026-10-11T09:00:00.000Z');
CREATE TABLE outreach_drafts (
  id                        TEXT PRIMARY KEY,
  owner_id                  TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  lead_id                   TEXT NOT NULL REFERENCES leads(id)     ON DELETE CASCADE,
  campaign_id               TEXT REFERENCES campaigns(id) ON DELETE SET NULL,
  channel                   TEXT NOT NULL
                              CHECK (channel IN ('email','contact_form','instagram_dm','linkedin_manual','other')),
  subject                   TEXT,
  body                      TEXT NOT NULL,
  personalization_evidence  TEXT NOT NULL DEFAULT '[]',
  status                    TEXT NOT NULL DEFAULT 'needs_review'
                              CHECK (status IN ('draft','needs_review','approved','contacted','replied','archived')),
  source                    TEXT NOT NULL DEFAULT 'template'
                              CHECK (source IN ('template','ai')),
  needs_human_review        INTEGER NOT NULL DEFAULT 1 CHECK (needs_human_review IN (0, 1)),
  approved_at               TEXT,
  contacted_at              TEXT,
  replied_at                TEXT,
  created_at                TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at                TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
INSERT INTO "outreach_drafts" ("id","owner_id","lead_id","campaign_id","channel","subject","body","personalization_evidence","status","source","needs_human_review","approved_at","contacted_at","replied_at","created_at","updated_at") VALUES('draft_haveli_01','ccc2a329-a7a0-4147-ba6d-827934124a5b','lead_haveli','cmp_mumbai_jewellery_q4','instagram_dm',NULL,'Namaste — I''m Nihar, I run a small design studio in Mumbai called DWN. I was looking at the Haveli work and the craftsmanship clearly belongs in a space of its own online. If a focused brand site is something you''ve been considering, I''d love to share a short note on what we could put together. No pitch deck, just a real conversation if the timing fits.','["Haveli has no public website today.","Their Instagram shows active posting within the last two weeks."]','needs_review','template',1,NULL,NULL,NULL,'2026-10-13T09:00:00.000Z','2026-10-13T09:00:00.000Z');
INSERT INTO "outreach_drafts" ("id","owner_id","lead_id","campaign_id","channel","subject","body","personalization_evidence","status","source","needs_human_review","approved_at","contacted_at","replied_at","created_at","updated_at") VALUES('draft_marine_01','ccc2a329-a7a0-4147-ba6d-827934124a5b','lead_marine_drive','cmp_restaurant_mobile','email','A quick note from a local design studio (your site)','Hi — I''m Nihar from DWN, a design studio in Mumbai. I noticed Marine Drive Bistro''s website has been intermittently unreachable over the last couple of days. Given how much of your traffic now comes via phones, a small focused rebuild — menu first, reservations one tap away — would restore the online face of what''s already a strong physical experience. Happy to share a one-pager with the specifics if useful.','["Audit showed HTTP 522 on three attempts across 48h.","Google Business shows reviews within the last 5 days — restaurant is actively operating."]','approved','template',1,'2026-10-13T09:00:00.000Z',NULL,NULL,'2026-10-12T09:00:00.000Z','2026-10-13T09:00:00.000Z');
INSERT INTO "outreach_drafts" ("id","owner_id","lead_id","campaign_id","channel","subject","body","personalization_evidence","status","source","needs_human_review","approved_at","contacted_at","replied_at","created_at","updated_at") VALUES('draft_lotus_01','ccc2a329-a7a0-4147-ba6d-827934124a5b','lead_lotus_skincare','cmp_d2c_audits','email','Three CTAs on Lotus''s homepage — a thought','Hi — I''m Nihar at DWN, a small design studio. I spent some time with the Lotus Skincare site today. The product and photography are strong, but the hero is competing with itself — Shop, Quiz, Newsletter all at similar weight. On paid traffic I''d expect the Quiz is the one earning the click. Would it be useful to sketch what the page would look like with a single primary action?','["Audit found three competing CTAs above the fold on lotus-skincare.example.","Hero image audit flagged 1.4 MB payload."]','contacted','template',1,'2026-10-08T09:00:00.000Z','2026-10-09T09:00:00.000Z',NULL,'2026-10-08T09:00:00.000Z','2026-10-09T09:00:00.000Z');
INSERT INTO "outreach_drafts" ("id","owner_id","lead_id","campaign_id","channel","subject","body","personalization_evidence","status","source","needs_human_review","approved_at","contacted_at","replied_at","created_at","updated_at") VALUES('draft_papertrail_01','ccc2a329-a7a0-4147-ba6d-827934124a5b','lead_papertrail_logistics','cmp_smb_automation','email','Spreadsheets and ops interns — a short idea','Hi — I''m Nihar from DWN. I noticed PaperTrail is hiring ops interns to help with spreadsheets. We''ve worked with a handful of mid-market SMBs on exactly that pattern — picking the one workflow eating the most hours and quietly replacing it with software. Totally fine if the shape of your ops is different, but if there''s a candidate workflow, I''d love 20 minutes to understand it.','["LinkedIn hiring post referenced ''help managing spreadsheets''.","Company LinkedIn posted about process improvement within the last 10 days."]','replied','template',1,'2026-10-09T09:00:00.000Z','2026-10-10T09:00:00.000Z','2026-10-12T09:00:00.000Z','2026-10-09T09:00:00.000Z','2026-10-12T09:00:00.000Z');
INSERT INTO "outreach_drafts" ("id","owner_id","lead_id","campaign_id","channel","subject","body","personalization_evidence","status","source","needs_human_review","approved_at","contacted_at","replied_at","created_at","updated_at") VALUES('draft_soma_01','ccc2a329-a7a0-4147-ba6d-827934124a5b','lead_soma_wellness','cmp_d2c_audits','email','Thanks for the reply — next step?','Thanks for coming back on this. Would next Thursday or Friday work for a 25-minute call? I''ll put together a short note on what we''d typically prioritise for a brand like Soma before then.','["Prior reply from team@soma-teas.example on 2026-10-06 asked for scheduling."]','draft','template',1,NULL,NULL,NULL,'2026-10-13T09:00:00.000Z','2026-10-13T09:00:00.000Z');
INSERT INTO "outreach_drafts" ("id","owner_id","lead_id","campaign_id","channel","subject","body","personalization_evidence","status","source","needs_human_review","approved_at","contacted_at","replied_at","created_at","updated_at") VALUES('draft_ayur_01','ccc2a329-a7a0-4147-ba6d-827934124a5b','lead_ayur_bandra','cmp_clinic_websites','contact_form',NULL,'Hello — I noticed the AyurClinic Bandra contact form currently returns an error. Just a heads-up in case it''s reaching nobody. Separately I run a small design studio and we specialise in simple clinic websites with a working enquiry path — happy to share a short note if useful.','["Audit confirmed contact form submits return HTTP 500.","Site served over HTTP — not HTTPS."]','needs_review','template',1,NULL,NULL,NULL,'2026-10-13T09:00:00.000Z','2026-10-13T09:00:00.000Z');
CREATE TABLE activities (
