  lead_id        TEXT REFERENCES leads(id)     ON DELETE CASCADE,
  campaign_id    TEXT REFERENCES campaigns(id) ON DELETE SET NULL,
  activity_type  TEXT NOT NULL,
  title          TEXT NOT NULL,
  description    TEXT,
  metadata       TEXT,
  created_at     TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
