INSERT INTO "activities" ("id","owner_id","lead_id","campaign_id","activity_type","title","description","metadata","created_at") VALUES('act_02','ccc2a329-a7a0-4147-ba6d-827934124a5b','lead_papertrail_logistics',NULL,'meeting_booked','Meeting booked with PaperTrail Logistics','Thursday 11:00 — intro + workflow deep-dive.',NULL,'2026-10-11T09:00:00.000Z');
INSERT INTO "activities" ("id","owner_id","lead_id","campaign_id","activity_type","title","description","metadata","created_at") VALUES('act_03','ccc2a329-a7a0-4147-ba6d-827934124a5b','lead_marine_drive',NULL,'draft_approved','Approved email for Marine Drive Bistro','Ready to send manually.',NULL,'2026-10-13T09:00:00.000Z');
INSERT INTO "activities" ("id","owner_id","lead_id","campaign_id","activity_type","title","description","metadata","created_at") VALUES('act_04','ccc2a329-a7a0-4147-ba6d-827934124a5b','lead_haveli',NULL,'draft_created','Draft created for Haveli Fine Jewels','Instagram DM — needs review.',NULL,'2026-10-13T09:00:00.000Z');
INSERT INTO "activities" ("id","owner_id","lead_id","campaign_id","activity_type","title","description","metadata","created_at") VALUES('act_05','ccc2a329-a7a0-4147-ba6d-827934124a5b','lead_ayur_bandra',NULL,'audit_run','Audit completed for AyurClinic Bandra','Found 2 high-severity findings (HTTPS, broken form).',NULL,'2026-10-12T09:00:00.000Z');
