CREATE TABLE service_offerings (
  id                 TEXT PRIMARY KEY,
  owner_id           TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  name               TEXT NOT NULL,
  description        TEXT NOT NULL DEFAULT '',
  ideal_customer     TEXT NOT NULL DEFAULT '',
  value_proposition  TEXT NOT NULL DEFAULT '',
  case_study_url     TEXT,
  is_active          INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)),
  created_at         TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at         TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
INSERT INTO "service_offerings" ("id","owner_id","name","description","ideal_customer","value_proposition","case_study_url","is_active","created_at","updated_at") VALUES('svc_website','ccc2a329-a7a0-4147-ba6d-827934124a5b','Website design & build','Modern responsive websites with strong information architecture and conversion-focused content.','Businesses whose website is missing, outdated, or hurting their credibility.','A clear, fast, mobile-first site that reflects the brand and converts visitors into enquiries.',NULL,1,'2026-10-14T09:00:00.000Z','2026-10-14T09:00:00.000Z');
INSERT INTO "service_offerings" ("id","owner_id","name","description","ideal_customer","value_proposition","case_study_url","is_active","created_at","updated_at") VALUES('svc_ecommerce','ccc2a329-a7a0-4147-ba6d-827934124a5b','E-commerce experience','Shopify / headless storefronts tuned for product storytelling and checkout performance.','D2C brands scaling past a generic storefront template.','A storefront that matches the product''s quality, not a stock Shopify theme.',NULL,1,'2026-10-14T09:00:00.000Z','2026-10-14T09:00:00.000Z');
INSERT INTO "service_offerings" ("id","owner_id","name","description","ideal_customer","value_proposition","case_study_url","is_active","created_at","updated_at") VALUES('svc_brand','ccc2a329-a7a0-4147-ba6d-827934124a5b','Brand identity & digital design','Logo systems, type pairings, color, and digital asset libraries built for consistency.','Studios and brands whose visual identity has drifted or never fully existed.','A coherent identity across every surface, with design tokens that teams can actually use.',NULL,1,'2026-10-14T09:00:00.000Z','2026-10-14T09:00:00.000Z');
INSERT INTO "service_offerings" ("id","owner_id","name","description","ideal_customer","value_proposition","case_study_url","is_active","created_at","updated_at") VALUES('svc_automation','ccc2a329-a7a0-4147-ba6d-827934124a5b','AI workflow automation','Internal tools, scripts, and AI integrations that remove repeated manual steps.','Teams running their business on spreadsheets, email forwards, and copy-paste.','Hours back per week on the operations the owner shouldn''t be doing by hand.',NULL,1,'2026-10-14T09:00:00.000Z','2026-10-14T09:00:00.000Z');
INSERT INTO "service_offerings" ("id","owner_id","name","description","ideal_customer","value_proposition","case_study_url","is_active","created_at","updated_at") VALUES('svc_landing','ccc2a329-a7a0-4147-ba6d-827934124a5b','Landing pages & campaign microsites','Single-focus pages tuned for a specific launch, offer, or audience.','Brands running paid traffic to a page that isn''t earning the click.','A landing experience that respects the visitor''s intent and reads like it was written by a human.',NULL,1,'2026-10-14T09:00:00.000Z','2026-10-14T09:00:00.000Z');
INSERT INTO "service_offerings" ("id","owner_id","name","description","ideal_customer","value_proposition","case_study_url","is_active","created_at","updated_at") VALUES('svc_software','ccc2a329-a7a0-4147-ba6d-827934124a5b','Custom software & internal tools','Bespoke web applications and internal dashboards built for a specific operational need.','Businesses outgrowing off-the-shelf tools or stitching together three SaaS products.','Software that fits the actual workflow instead of forcing the workflow to fit the software.',NULL,1,'2026-10-14T09:00:00.000Z','2026-10-14T09:00:00.000Z');
